//#region Types ························································································¬

type GooeyTheme = 'vanilla' | 'flat' | 'scout' | (string & {})

export interface GooeyElements {
	root: HTMLElement
	container: HTMLElement
	wrapper: HTMLElement
	settingsFolder: Folder
}

export interface GooeyOptions {
	__type: 'GooeyOptions'

	/**
	 * The title of the Gooey.
	 * @default 'gooey'
	 */
	title: string

	/**
	 * Defines which properties to persist in localStorage, and under which
	 * key, if any.  If `true`, the {@link GUI_STORAGE_DEFAULTS} will be used.
	 * If `false`, no state will be persisted.
	 * @default true
	 */
	storage: boolean | Partial<GooeyStorageOptions>

	/**
	 * The container to append the gooey to.
	 * @default 'body'
	 */
	// container: HTMLElement
	container: string | HTMLElement | 'document' | 'body'

	/**
	 * Whether the gooey is draggable.
	 * @default true
	 */
	draggable: boolean

	/**
	 * Whether the gooey is resizable.
	 * @default true
	 */
	resizable: boolean

	/**
	 * The title of the theme to use for the gooey.  To add your own themes,
	 * use {@link GooeyOptions.themes|themes}.  Ignored under {@link parentGooey} — a child
	 * follows the parent's theme.
	 * @default 'vanilla'
	 */
	theme: GooeyTheme

	/**
	 * The themes available to the gooey.
	 * @defaultValue [ {@link theme_default|default}, {@link theme_flat|flat}, {@link theme_scout|scout} ]
	 */
	themes: Theme[]

	/**
	 * The initial {@link Themer.mode|theme mode}.
	 * @default 'dark'
	 */
	themeMode: 'light' | 'dark' | 'system'

	/**
	 * The gooey's initial position on the screen.  If `undefined`, the gooey will
	 * be placed in the top-right corner of the screen.
	 *
	 * This value can either be a {@link Placement} string, or an object with
	 * `x` and `y` properties representing the position in pixels.
	 * @default 'top-right'
	 */
	position: Placement | { x: number; y: number }

	/**
	 * The margin in pixels to apply to the placement.  Can be a number
	 * to apply the same margin to both x and y, or an object with x
	 * and y properties to apply different margins to each axis.
	 * @default 16
	 */
	margin: number | { x?: number; y?: number }

	/**
	 * The initial width of the gooey in pixels.
	 *
	 * @remarks This can also be set by overriding the `--gooey-root_width` CSS custom property on
	 * the {@link Gooey.element} element `.gooey-root`, which is responsible for the root width.
	 *
	 * A {@link GooeyOptions.minWidth|minWidth} / {@link GooeyOptions.maxWidth|maxWidth} given
	 * explicitly wins over this.  Without one, a `width` below the default minimum lowers that
	 * minimum so the gooey can actually be as narrow as it was asked to be.
	 * @default undefined
	 */
	width?: number

	/**
	 * The narrowest the gooey may be, as a resize floor and a css `min-width` on
	 * {@link Gooey.element}.  A number is pixels, a string is passed through as a css length
	 * (`'12rem'`, `'30%'`), and `'none'` leaves it unbounded.
	 *
	 * @remarks Writes the `--gooey-root_min-width` custom property inline on `.gooey-root`, so it
	 * survives a theme or mode change.  When omitted, the `:where(.gooey-root)` default in
	 * `gooey.scss` (`20rem`) applies.
	 * @default undefined
	 */
	minWidth?: number | string

	/**
	 * The widest the gooey may be, as a resize ceiling and a css `max-width` on
	 * {@link Gooey.element}.  A number is pixels, a string is passed through as a css length, and
	 * `'none'` leaves it unbounded -- which is what a gooey used as a window rather than a control
	 * panel usually wants, since the default `35rem` silently stops a drag at 560px.
	 *
	 * @remarks Writes the `--gooey-root_max-width` custom property inline on `.gooey-root`, so it
	 * survives a theme or mode change.  When omitted, the `:where(.gooey-root)` default in
	 * `gooey.scss` (`35rem`) applies.
	 * @default undefined
	 */
	maxWidth?: number | string

	/**
	 * The tallest the gooey's content may grow before it scrolls, as a css `max-height` on the
	 * root content element.  A number is pixels, a string is passed through as a css length
	 * (`'90vh'`), and `'none'` leaves it unbounded.
	 *
	 * @remarks This caps the scrolling content, not the header -- the root itself is
	 * `height: fit-content`, and the resize grabbers are left/right only.  Writes the
	 * `--gooey-root_max-height` custom property inline on `.gooey-root`, so it survives a theme or
	 * mode change.  When omitted, the `:where(.gooey-root)` default in `gooey.scss` (`90vh`)
	 * applies.
	 * @default undefined
	 */
	maxHeight?: number | string

	/**
	 * The initial expanded state of the gooey.
	 * @default false
	 */
	closed: boolean

	/**
	 * The initial hidden state of the gooey.
	 * @default false
	 */
	hidden?: boolean

	/**
	 * Presets to make available in the gooey.
	 * @default []
	 */
	presets?: GooeyPreset[]

	/**
	 * The default preset to load when the gooey is created, or the initial gooey state if undefined.
	 * @default undefined
	 */
	defaultPreset?: GooeyPreset

	/**
	 * A unique id for the gooey's root element.
	 * @default {@link nanoid}
	 */
	id?: string

	/**
	 * Whether to load the default font for use.  Set to `false` if you're overwriting
	 * the `--gooey-font-family` variable in your theme.
	 * @default true
	 */
	loadDefaultFont?: boolean

	/**
	 * Any {@link FolderOptions} for the builtin global settings folder.  It also accepts 2
	 * additional settings, `uiFolder` and `presetsFolder`, which are {@link FolderOptions}
	 * for the 2 sub-folders.
	 * @default { closed: true }
	 *
	 * `false` hides the settings folder and omits the toolbar's settings button, for a gooey
	 * used as a plain window rather than a control panel.  The folder itself is still built, so
	 * the {@link Gooey.themer|themer} and {@link Gooey.presetManager|preset manager} behave
	 * exactly as they otherwise would -- there is simply no way in.
	 */
	settingsFolder?:
		| false
		| (Partial<FolderOptions> & {
				uiFolder?: Partial<FolderOptions>
				presetsFolder?: Partial<FolderOptions>
		  })

	/**
	 * Another {@link Gooey} to share a {@link WindowManager} and {@link Themer} with.  Child
	 * gooeys stack against their parent instead of floating in a z-order of their own, and
	 * follow its theme.  Each still keeps its own {@link GooeyOptions.storage|storage} key, so
	 * position and size persist per window.
	 *
	 * Disposing a child leaves the parent's window manager and themer alone.
	 *
	 * @default undefined
	 */
	parentGooey?: Gooey

	/**
	 * An offset to apply to the initial position of the gooey.
	 * @default { x: 0, y: 0 }
	 */
	offset?: { x?: number; y?: number }
}

export interface GooeyOptionsInternal extends GooeyOptions {
	/**
	 * todo - this needs to be public, maybe as `GooeyOptions.parentGooey` so the user doesn't
	 * todo - have to think about the window manager?
	 * @internal
	 */
	_windowManager?: WindowManager

	/**
	 * @internal
	 */
	_themer?: Themer
}

/**
 * Defines which properties to persist in localStorage, and under which
 * key.
 * @example
 * // defaults:
 * {
 *   key: 'gooey',
 *   closed: true,
 *   theme: true,
 *   presets: true,
 *   position: false,
 *   size: false,
 * }
 */
export interface GooeyStorageOptions {
	__type: 'GooeyStorageOptions'

	/**
	 * Prefix to use for localStorage keys.
	 *
	 * @remarks The provided string is prepended to the gooey's title, lowercased, and hyphens
	 * are replaced with spaces.  For example, a gooey titled `"Foo Bar"` is stored as
	 * `"foo-bar::gooey"`.
	 *
	 * @default "default"
	 */
	key: string

	/**
	 * Whether to persist the folder's expanded state.
	 * @default true
	 */
	closed?: boolean

	/**
	 * Whether to persist the theme.
	 * @default true
	 */
	theme?: boolean

	/**
	 * Whether to persist the gooey's position.
	 * @default false
	 */
	position?: boolean

	/**
	 * Whether to persist the gooey's size.
	 * @default false
	 */
	size?: boolean

	/**
	 * Whether to persist the gooey's presets.
	 * @default true
	 */
	presets?: boolean
}

export interface GooeyPreset {
	__type: 'GooeyPreset'
	__version: string | number
	id: string
	title: string
	data: FolderPreset
}
//#endregion

